'use client';

import Link from 'next/link';
import { FormEvent, useEffect, useState } from 'react';
import { useParams } from 'next/navigation';
import { api } from '@/lib/api';
import { Avatar } from '@/components/avatar';
import { StatePanel } from '@/components/state-panel';
import { formatRelativeTime } from '@/lib/format';

type Detail = { id: string; kind: 'PROJECT' | 'SERVICE'; status: string; title: string; summary: string; description: string; coverUrl: string | null; lookingForTeam: boolean; priceText: string | null; contactNote: string | null; links: string[]; updatedAt: string; interactionCount: number; isOwner: boolean; owner: { username: string; displayName: string; avatarUrl: string | null; forrumId: number; bio: string | null }; community: { slug: string; name: string; accentColor: string } | null; publication: { slug: string; title: string | null } | null };
export default function PortfolioDetailPage() { const { id } = useParams<{ id: string }>(); const [data, setData] = useState<Detail | null>(null); const [error, setError] = useState(''); const [message, setMessage] = useState(''); const [requestOpen, setRequestOpen] = useState(false); const load = () => api<Detail>(`/portfolio/${id}`).then((value) => { setData(value); setError(''); }).catch((cause) => setError(cause.message)); useEffect(() => { void load(); }, [id]); async function request(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!data) return; const form = new FormData(event.currentTarget); try { await api('/interactions', { method: 'POST', body: JSON.stringify({ targetUsername: data.owner.username, type: data.kind === 'SERVICE' ? 'SERVICE' : 'PROJECT', title: form.get('title'), description: form.get('description'), portfolioItemId: data.id, communitySlug: data.community?.slug, publicationSlug: data.publication?.slug }) }); setMessage('Запрос отправлен владельцу. Отзыв станет доступен только после двустороннего завершения.'); setRequestOpen(false); } catch (cause) { setError(cause instanceof Error ? cause.message : 'Не удалось отправить запрос'); } } if (!data) return <StatePanel kind={error ? 'error' : 'loading'} title={error ? 'Карточка недоступна' : 'Загрузка карточки'}>{error && <p>{error}</p>}</StatePanel>; return <div className="portfolio-detail" style={{ '--portfolio-accent': data.community?.accentColor ?? '#3157D5' } as React.CSSProperties}><p><Link className="muted" href={data.kind === 'PROJECT' ? '/projects' : '/services'}>← {data.kind === 'PROJECT' ? 'Все проекты' : 'Все услуги'}</Link></p><main className="card portfolio-detail-main">{data.coverUrl && <div className="portfolio-detail-cover" style={{ backgroundImage: `url(${data.coverUrl})` }}/>}<div className="publication-topline"><span className="type-label">{data.kind === 'PROJECT' ? 'Проект' : 'Услуга'}</span>{data.lookingForTeam && <span className="portfolio-team-label">Ищет команду</span>}</div><h1>{data.title}</h1><p className="lead">{data.summary}</p><div className="portfolio-description">{data.description.split('\n').map((line, index) => <p key={index}>{line}</p>)}</div>{data.priceText && <div className="portfolio-fact"><strong>Условия</strong><span>{data.priceText}</span></div>}{data.contactNote && <div className="portfolio-fact"><strong>Связь</strong><span>{data.contactNote}</span></div>}{data.links.length > 0 && <div className="portfolio-links">{data.links.map((link) => <a href={link} key={link} target="_blank" rel="noreferrer">Открыть ссылку ↗</a>)}</div>}{data.publication && <Link className="linked-publication" href={`/p/${data.publication.slug}`}><span>Связанная постоянная тема</span><strong>{data.publication.title || 'Открыть обсуждение'}</strong></Link>}{message && <div className="success-box">{message}</div>}{error && <div className="error-box">{error}</div>}{data.isOwner ? <Link className="button" href="/portfolio">Управлять карточкой</Link> : requestOpen ? <form className="interaction-inline-form" onSubmit={request}><h2>Запросить взаимодействие</h2><p className="muted">Это не оплата и не гарантия сделки. Владелец должен подтвердить запрос.</p><label>Кратко о задаче<input name="title" minLength={4} maxLength={140} required defaultValue={data.kind === 'SERVICE' ? `Запрос услуги: ${data.title}` : `Участие в проекте: ${data.title}`}/></label><label>Что хотите обсудить<textarea name="description" minLength={10} maxLength={2000} required/></label><div className="inline-actions"><button className="button">Отправить</button><button type="button" className="button ghost" onClick={() => setRequestOpen(false)}>Отмена</button></div></form> : <button type="button" className="button" onClick={() => setRequestOpen(true)}>{data.kind === 'SERVICE' ? 'Обсудить услугу' : 'Связаться по проекту'}</button>}</main><aside className="card portfolio-owner-card"><Link href={`/u/${data.owner.username}`}><Avatar name={data.owner.displayName} url={data.owner.avatarUrl} size={64}/><div><strong>{data.owner.displayName}</strong><span>@{data.owner.username} · FORRUM ID {data.owner.forrumId}</span></div></Link>{data.owner.bio && <p>{data.owner.bio}</p>}{data.community && <Link className="text-link" href={`/communities/${data.community.slug}`}>{data.community.name}</Link>}<dl><div><dt>Подтверждённых взаимодействий</dt><dd>{data.interactionCount}</dd></div><div><dt>Обновлено</dt><dd>{formatRelativeTime(data.updatedAt)}</dd></div></dl></aside></div>; }
